#include <bits/stdc++.h>
using namespace std;

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m;
    cin >> n >> m;
    vector<vector<int>> g(n, vector<int>(m));
    for(int i = 0; i < n; i++)
        for(int j = 0; j < m; j++)
            cin >> g[i][j];

    // Paridades adjacentes devem ser diferentes -> xadrez.
    // Padrao A: celula (i,j) deve ter paridade (i+j)%2 (0-indexed).
    // Padrao B: complementar.
    int costA = 0;
    for(int i = 0; i < n; i++)
        for(int j = 0; j < m; j++)
            if(g[i][j] % 2 != (i + j) % 2) costA++;

    int total = n * m;
    int best = min(costA, total - costA);

    // flip = 0 -> padrao A se for o melhor, senao padrao B (complemento)
    int flip = (costA <= total - costA) ? 0 : 1;

    cout << best << "\n";
    for(int i = 0; i < n; i++){
        for(int j = 0; j < m; j++){
            int t = (i + j + flip) % 2;   // paridade alvo
            int v = g[i][j];
            if(v % 2 != t) v++;           // 1 gota ajusta a paridade
            cout << v << " \n"[j == m - 1];
        }
    }
    return 0;
}
